void update_moby_offset_motion(struct Moby *moby) __asm__("FUN_L07_0031a9e8");

void update_moby_offset_motion(struct Moby *moby) {
    enum {
        MOVING_MOBY_INITIALIZE = 0,
        MOVING_MOBY_WAIT_AT_HOME = 1,
        MOVING_MOBY_MOVE_TO_OFFSET = 2,
        MOVING_MOBY_WAIT_AT_OFFSET = 3,
        MOVING_MOBY_RETURN_HOME = 4
    };
    struct L07MovingVars *vars = (struct L07MovingVars *)moby->pvars;
    struct Moby *target;
    Vec4 next;
    Vec4 start;
    float distance;
    float time;
    int force_end;
    int force_start;
    u8 spawn_id;
    int no_spawn;

    if (moby->mission != 0xff && visited52[moby->mission + current_level_index * 16] == 0xff)
        vars->target = -1;
    spawn_id = moby->mission;
    force_end = 0;
    /* Fakematch: the 0xFF compare needs its own variable for retail register order. */
    no_spawn = 0xff;
    force_start = 0;
    if (D_L07_0015FC88[spawn_id] == no_spawn) {
        if (vars->forceReturn != 0)
            force_end = 1;
        else
            force_start = 1;
    }

    switch (moby->state) {
    case MOVING_MOBY_INITIALIZE:
        qcopy(&vars->home, &moby->pos);
        if (vars->indicator != -1)
            D_L07_00184528[vars->indicator] = 0;
        moby->state = 1;
        vars->home.w = 0;
        return;
    case MOVING_MOBY_WAIT_AT_HOME:
        if (force_start)
            return;
        if (!force_end && vars->target != -1 &&
            (target = &D_L07_0015FFD8[vars->target]) != 0 &&
            target->state != 0xfe && target->state != 0xfd &&
            target->state != vars->openState)
            return;
        start.q = 0;
        start.f[0] = vars->destination.x;
        start.f[1] = vars->destination.y;
        start.f[2] = vars->destination.z;
        next.q = start.q;
        vars->home.w = vector_length_xyz(&next);
        if (vars->startSound != -1)
            FUN_0022da68(vars->startSound, 0, moby);
        moby->state = 2;
        break;
    case MOVING_MOBY_MOVE_TO_OFFSET:
        if (force_start || (!force_end && vars->target != -1 &&
            (target = &D_L07_0015FFD8[vars->target]) != 0 &&
            target->state != 0xfe && target->state != 0xfd &&
            target->state == vars->shutState)) {
            if (vars->startSound != -1)
                FUN_0022da68(vars->startSound, 0, moby);
            moby->state = 4;
            break;
        }
        start.q = 0;
        start.f[0] = vars->destination.x;
        start.f[1] = vars->destination.y;
        start.f[2] = vars->destination.z;
        next.q = start.q;
        transform_vector_xyz(&next, &next, &moby->rot_row0);
        scale_vector_xyz(&start, &next, vars->destination.w * frame_time);
        add_vector_xyz(&moby->pos, &moby->pos, &start);
        time = vars->home.w - vars->destination.w * frame_time;
        vars->home.w = time;
        if (!(time < 0.0f))
            return;
        add_vector_xyz(&moby->pos, &vars->home, &next);
        vars->home.w = 0;
        if (vars->indicator != -1)
            D_L07_00184528[vars->indicator] = 1;
        moby->state = 3;
        if (vars->endSound != -1)
            FUN_0022da68(vars->startSound, 0, moby);
        return;
    case MOVING_MOBY_WAIT_AT_OFFSET:
        if (!force_start && (force_end || vars->target == -1 ||
            (target = &D_L07_0015FFD8[vars->target]) == 0 ||
            target->state == 0xfe || target->state == 0xfd ||
            target->state != vars->shutState))
            return;
        vars->home.w = 0;
        if (vars->startSound != -1)
            FUN_0022da68(vars->startSound, 0, moby);
        moby->state = 4;
        break;
    case MOVING_MOBY_RETURN_HOME:
        if (!force_start && (force_end || vars->target == -1 ||
            (target = &D_L07_0015FFD8[vars->target]) == 0 ||
            target->state == 0xfe || target->state == 0xfd ||
            target->state == vars->openState)) {
            if (vars->startSound != -1)
                FUN_0022da68(vars->startSound, 0, moby);
            moby->state = 2;
            break;
        }
        start.q = 0;
        start.f[0] = vars->destination.x;
        start.f[1] = vars->destination.y;
        start.f[2] = vars->destination.z;
        next.q = start.q;
        distance = vector_length_xyz(&next);
        scale_vector_xyz(&next, &next, -(vars->speed * frame_time));
        transform_vector_xyz(&start, &next, &moby->rot_row0);
        add_vector_xyz(&moby->pos, &moby->pos, &start);
        time = vars->home.w + vars->speed * frame_time;
        vars->home.w = time;
        if (!(distance < time))
            return;
        qcopy(&moby->pos, &vars->home);
        if (vars->startSound != -1)
            FUN_0022da68(vars->endSound, 0, moby);
        if (vars->indicator != -1)
            D_L07_00184528[vars->indicator] = 0;
        moby->state = 1;
        break;
    case 5:
        break;
    }
}
struct SwingGateVars {
    int target;     /* 0x00: moby index, -1 for none */
    int openState;  /* 0x04 */
    int shutState;  /* 0x08 */
    float speed;    /* 0x0C */
    float damp;     /* 0x10 */
    float rate;     /* 0x14 */
    float vel;      /* 0x18 */
};

extern struct Moby *D_L07_0015FFD8;
extern int FUN_0022da68(int, int, struct Moby *);
extern float fast_cos(float) __asm__("FUN_001f9dc8");
extern float fast_add_rotations(float, float) __asm__("FUN_001fa580");
extern float fast_subtract_rotations(float, float) __asm__("FUN_001fa5c8");

void update_swing_gate(struct Moby *moby) __asm__("FUN_L07_0031b3f0");

void update_swing_gate(struct Moby *moby) {
    enum {
        SWING_GATE_INITIALIZE = 0,
        SWING_GATE_WAIT_FOR_OPEN_CONDITION = 1,
        SWING_GATE_HOLD_ROTATION = 2,
        SWING_GATE_SWINGING = 3,
        SWING_GATE_RETURN_TO_ZERO = 4
    };
    struct SwingGateVars *vars = (struct SwingGateVars *)moby->pvars;
    struct Moby *target;
    float updated_y_rotation;

    if (vars == 0)
        return;
    switch (moby->state) {
    case SWING_GATE_INITIALIZE:
        moby->rot.y = 0;
        moby->state = 1;
        vars->vel = 0;
        break;
    case SWING_GATE_WAIT_FOR_OPEN_CONDITION:
        if (vars->target != -1 && (target = &D_L07_0015FFD8[vars->target]) != 0 &&
            target->state != 0xFE && target->state != 0xFD && target->state != vars->openState)
            return;
        vars->vel = vars->speed * frame_time;
        moby->rot.y = vars->vel;
        FUN_0022da68(0, 0, moby);
        moby->state = 3;
        break;
    case SWING_GATE_HOLD_ROTATION:
        break;
    case SWING_GATE_SWINGING:
        vars->vel = fast_add_rotations(vars->vel, fast_cos(moby->rot.y) * (vars->speed * frame_time));
        moby->rot.y = fast_add_rotations(moby->rot.y, vars->vel);
        vars->vel = vars->vel * vars->damp;
        target = &D_L07_0015FFD8[vars->target];
        if (target == 0 || target->state == 0xFE || target->state == 0xFD)
            break;
        if (target->state != vars->shutState)
            return;
        moby->state = 4;
        break;
    case SWING_GATE_RETURN_TO_ZERO:
        if (vars->target == -1 || (target = &D_L07_0015FFD8[vars->target]) == 0 ||
            target->state == 0xFE || target->state == 0xFD || target->state == vars->openState) {
            FUN_0022da68(0, 0, moby);
            moby->state = 2;
            break;
        }
        updated_y_rotation = fast_subtract_rotations(moby->rot.y, vars->rate);
        moby->rot.y = updated_y_rotation;
        if (0.0f < updated_y_rotation) {
            moby->rot.y = 0;
            vars->vel = 0;
            moby->state = 1;
        }
        break;
    case 5:
        break;
    }
}
